def compute(vars):
    start_value = vars["v1"]
    end_value = vars["v2"]
    years = 2022 - 2019

    if start_value == 0 or years == 0:
        return None

    growth_factor = end_value / start_value
    cagr = growth_factor ** (1 / years)
    cagr_rate = (cagr - 1) * 100
    result = round(cagr_rate, 2)

    return {
        "value": result,
        "trace": {
            "start_value": start_value,
            "end_value": end_value,
            "years": years,
            "growth_factor": growth_factor,
            "cagr": cagr,
            "cagr_rate_percent": cagr_rate,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "%"
            }
        }
    }

